'use strict';
const CHECKIN_KEY='antar-checkins-v1';
let checkins=[],checkinReadError=false,logDraft=null,editingCheckin=null,lastDeletedCheckin=null,monthDay='',monthOffset=0;
let personalLearning=true,logMoodPickerOpen=false;
try{const raw=localStorage.getItem(CHECKIN_KEY);if(raw){const parsed=JSON.parse(raw);if(!Array.isArray(parsed)||!parsed.every(AntarPatterns.valid))checkinReadError=true;else checkins=parsed;}personalLearning=localStorage.getItem('antar-learning')!=='off';}catch{checkinReadError=true;}
const situationChoices=[['work','Work or studies'],['relationships','Relationships'],['family','Family'],['comparison','Comparison or self-worth'],['future','Future or decisions'],['alone','Feeling alone'],['energy','Sleep or energy'],['other','Something else'],['unsure','Not sure']];
const activityChoices=[['','Nothing to record'],['reset','Quiet reset'],['reflection','A reflection or excerpt'],['story','An interactive story'],['rest','Rest or a break'],['connection','Talking to someone'],['movement','A little movement'],['other','Something else']];
const nameFor=(options,id)=>options.find(x=>x[0]===id)?.[1]||id;
const localInput=date=>new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);
function monthKey(){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+monthOffset);return AntarPatterns.dateKey(d).slice(0,7)}
function monthLabel(key){const [y,m]=key.split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('en-IN',{month:'long',year:'numeric'})}
function beginCheckin(excerptId=''){const entry=excerptBank?.find(e=>e.id===excerptId);editingCheckin=null;logMoodPickerOpen=false;logDraft={at:localInput(new Date()),moods:selected.length?[...selected]:['unsure'],intensity,nuance:nuance||'',need:typeof feltNeed!=='undefined'?feltNeed:'',situation:'unsure',duration:'',activity:entry?'reflection':'',outcome:'unsure',note:'',excerptId:entry?.id||''};go('log');}
function commitCheckins(next){try{const raw=JSON.parse(localStorage.getItem(CHECKIN_KEY)||'[]');if(!Array.isArray(raw)||!raw.every(AntarPatterns.valid))throw Error('invalid-history');const merged=AntarMemory.mergeChanges(checkins,next,raw);if(merged.length>5000)throw Error('too-many');localStorage.setItem(CHECKIN_KEY,JSON.stringify(merged));checkins=merged;return true}catch{toast('History could not be saved safely. Your draft is still here. Export a backup or check browser storage.');return false}}
function checkinForm(){if(!logDraft)logDraft={at:localInput(new Date()),moods:selected.length?[...selected]:['unsure'],intensity,nuance:nuance||'',need:typeof feltNeed!=='undefined'?feltNeed:'',situation:'unsure',duration:'',activity:'',outcome:'unsure',note:'',excerptId:''};const d=logDraft;return `${button('‹ My month','go-month','back')}<h1>${editingCheckin?'Is moment ko edit karein.':'Ek chhota sa check-in.'}</h1><p class="sub">Low, overwhelmed, ya stuck—jo tum record karna chaho. Roz bharna zaroori nahi.${hi('Skip kiye hue din ka koi matlab hum assume nahi karenge.')}</p>${checkinReadError?'<div class="warning">Saved history could not be read. To avoid overwriting it, saving is paused. Open “Data & privacy” in My month to download the raw history or clear it explicitly.</div>':''}<div class="field">Kaisa lag raha tha?</div><p class="sub">${d.moods.map(id=>esc(moodData.find(m=>m.id===id)?.name||id)).join(' + ')||'Choose a feeling'}</p><details id="log-moods" ${logMoodPickerOpen?'open':''}><summary>Feelings badalni hain? <span class="small">Up to 3</span></summary><div class="chips">${moodData.map(m=>`<button class="chip ${d.moods.includes(m.id)?'selected':''}" data-log-mood="${m.id}" aria-pressed="${d.moods.includes(m.id)}">${m.name}${hi(m.hi)}</button>`).join('')}</div></details><label class="field" for="log-intensity">Kitna heavy tha? <span id="log-intensity-label">${d.intensity}/5</span></label><input id="log-intensity" type="range" min="1" max="5" value="${d.intensity}"><label class="field" for="log-situation">Kis cheez ke aas-paas?</label><select id="log-situation" class="section-select">${situationChoices.map(([id,label])=>`<option value="${id}" ${d.situation===id?'selected':''}>${label}</option>`).join('')}</select><details><summary>Need, time, duration, and an optional note</summary><label class="field" for="log-need">What did you need? <span class="small">(optional)</span></label><select id="log-need" class="section-select">${needOptions(d.need,false)}</select><label class="field" for="log-at">When was this?</label><input id="log-at" type="datetime-local" value="${esc(d.at)}" max="${localInput(new Date())}"><label class="field" for="log-duration">Estimated minutes <span class="small">(optional)</span></label><input id="log-duration" type="number" inputmode="numeric" min="0" max="1440" value="${esc(d.duration)}" placeholder="Leave blank if you don’t know"><p class="small">A rough estimate is enough. Unspecified time is kept unknown, not counted as zero downtime.</p><label class="field" for="log-note">Ek line, agar chaaho</label><textarea id="log-note" maxlength="600" placeholder="What would future-you find useful to remember?">${esc(d.note)}</textarea></details><details ${d.excerptId?'open':''}><summary>Kuch try kiya? Did it help? <span class="small">(optional)</span></summary>${d.excerptId?'<p class="small">This entry can include your feedback on the passage you chose.</p>':''}<label class="field" for="log-activity">What did you try?</label><select id="log-activity" class="section-select">${activityChoices.map(([id,label])=>`<option value="${id}" ${d.activity===id?'selected':''}>${label}</option>`).join('')}</select>${d.feltChange?`<p class="small">Your follow-up: ${esc({lighter:'Thoda halka',same:'Same sa',heavier:'Aur heavy'}[d.feltChange]||d.feltChange)}. This records felt change, not causation.</p>`:''}<label class="field" for="log-activity-detail">Your words for this action <span class="small">(optional)</span></label><input id="log-activity-detail" type="text" maxlength="120" value="${esc(d.activityDetail||'')}" placeholder="For example: ten minutes on the terrace"><div class="chips">${[['helped','Thoda helped'],['not-helped','Didn’t help'],['unsure','Not sure yet']].map(([id,label])=>`<button class="chip ${d.outcome===id?'selected':''}" data-log-outcome="${id}" aria-pressed="${d.outcome===id}">${label}</button>`).join('')}</div></details><p class="note">Saving keeps these personal details in this browser on this device. They aren’t sent to AI or synced, and aren’t encrypted by the app. Export a backup if you want to keep them when changing devices.</p>${button(editingCheckin?'Save changes':'Save this moment','save-checkin')}${button('Abhi save nahi karna','cancel-checkin','text-btn')}<p id="log-error" role="status" class="status"></p>`}
function calendarHTML(key,records){const [year,month]=key.split('-').map(Number),first=new Date(year,month-1,1),last=new Date(year,month,0).getDate(),today=AntarPatterns.dateKey(new Date());const counts=new Map();for(const r of records){const day=AntarPatterns.dateKey(new Date(r.at));counts.set(day,(counts.get(day)||0)+1)}return `<div class="calendar" aria-label="Logged moments in ${esc(monthLabel(key))}">${['S','M','T','W','T','F','S'].map((d,i)=>`<span class="calendar-weekday" aria-label="${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]}">${d}</span>`).join('')}${'<span></span>'.repeat(first.getDay())}${Array.from({length:last},(_,i)=>{const day=key+'-'+String(i+1).padStart(2,'0'),n=counts.get(day)||0;return `<button class="calendar-day ${n?'has-entry':''} ${monthDay===day?'selected':''}" data-month-day="${day}" ${day>today?'disabled':''} aria-label="${day}: ${n} saved ${n===1?'moment':'moments'}"><span>${i+1}</span><small>${n||'·'}</small></button>`}).join('')}</div><p class="small">A dot means no entry. Missing days aren’t treated as good or bad days.</p>`}
function patternInsights(summary){const cards=[];for(const x of summary.situations.slice(0,2))cards.push(`<div class="pattern-insight"><h3>A context that came up again</h3><p>${esc(nameFor(situationChoices,x.key))} appeared in ${x.count} difficult-moment entries across ${x.days} days this month.</p><p class="small">This is an association in your saved entries, not proof of what caused the feeling.</p></div>`);for(const x of summary.helpful.slice(0,2))cards.push(`<div class="pattern-insight"><h3>Something you rated helpful</h3><p>You marked ${esc(nameFor(activityChoices,x.key).toLowerCase())} helpful in ${x.helped} of ${x.rated} rated entries across ${x.days} days.</p><p class="small">Your own feedback—not a measured treatment effect. “Not sure” ratings aren’t included.</p></div>`);for(const x of summary.repeatedTimes.slice(0,1))cards.push(`<div class="pattern-insight"><h3>A time to be curious about</h3><p>${x.count} entries across ${x.days} days were logged in the ${esc(x.key)}.</p><p class="small">This uses the event times you saved, and can reflect when you tend to log.</p></div>`);return cards.length?cards.join(''):`<div class="panel"><h3>Abhi tumhe samajh rahe hain.</h3><p>${summary.loggedDays?'Your entries are here. There isn’t enough repeated evidence for a useful observation yet.':'No history yet. Save a moment when you want to—not because the calendar asks.'}</p><p class="small">Recurring contexts need at least 3 separate logged days. Helpful-activity summaries need at least 3 ratings on 3 days.</p></div>`}
function legacyMonthView(){const key=monthKey(),summary=AntarPatterns.summarize(checkins,key),records=summary.records.filter(e=>!monthDay||AntarPatterns.dateKey(new Date(e.at))===monthDay).reverse();return `<div class="section-head"><h1>Mera mahina.</h1>${button('+ A moment','new-checkin','small-add')}</div><p class="sub">Khud ko samajhne ki jagah. Progress report nahi.</p><div class="month-controls"><button data-month-shift="-1" aria-label="Previous month">‹</button><h2>${monthLabel(key)}</h2><button data-month-shift="1" aria-label="Next month" ${monthOffset>=0?'disabled':''}>›</button></div><div class="month-stats"><div><strong>${summary.loggedDays}</strong><span>days with entries</span></div><div><strong>${summary.difficultCount}</strong><span>saved moments</span></div><div><strong>${summary.durationCount?summary.knownMinutes+'m':'—'}</strong><span>${summary.durationCount?'estimated time in '+summary.durationCount+(summary.durationCount===1?' entry':' entries'):'duration not recorded'}</span></div></div>${calendarHTML(key,summary.records)}${monthDay?`<p class="note">Showing ${esc(monthDay)}. <button class="text-btn" data-action="clear-day">Show the whole month</button></p>`:''}<div class="section-head"><h2>What we’ve noticed</h2></div>${patternInsights(summary)}<details><summary>Within-month rhythm & monthly cycles</summary><p class="small">These are portions of the selected calendar month—not menstrual phases or predicted mood cycles.</p>${summary.thirds.map(x=>`<div class="phase-row"><span>${x.label}</span><span>${x.difficultDays} days with difficult moments / ${x.loggedDays} logged days</span></div>`).join('')}${summary.cycleObservations.map(x=>`<div class="pattern-insight"><h3>A repeated logging cluster</h3><p>In ${x.months.length} logged months (${x.months.map(esc).join(', ')}), ${x.label.toLowerCase()} had the largest count of saved difficult-moment days: ${x.days} days altogether.</p><p class="small">A logging pattern, not proof you feel worse then. Each qualifying month had entries in every third, with at least 3 days in the leading third and 2 more days than the next. There is no mood prediction.</p></div>`).join('')}<p class="note">One month cannot establish a repeating cycle. You currently have ${summary.observedMonths} months with at least 6 logged days. Even with more months, calendar patterns do not establish a cause or diagnosis.</p></details><label class="field"><input id="learning-toggle" type="checkbox" ${personalLearning?'checked':''}>Use my saved helpfulness feedback for passage suggestions</label><p class="small">Only feedback you explicitly save on a passage can affect its ranking. Mood and content-safety filters still apply. This learning happens in your browser.</p><div class="section-head"><h2>${monthDay?'That day’s moments':'Saved moments'}</h2></div>${records.length?records.map(e=>`<div class="checkin-row"><div class="inline-row"><strong>${new Date(e.at).toLocaleDateString('en-IN',{day:'numeric',month:'short'})} · ${new Date(e.at).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}</strong><span class="small">${e.intensity}/5${e.durationKnown?' · ~'+e.minutes+' min':''}</span></div><p>${e.moods.map(id=>esc(moodData.find(m=>m.id===id)?.name||id)).join(' + ')}</p><p class="small">${esc(nameFor(situationChoices,e.situation))}${e.activity?' · '+esc(nameFor(activityChoices,e.activity)):''}${e.activity&&e.outcome!=='unsure'?' · '+(e.outcome==='helped'?'marked helpful':'marked not helpful'):''}</p>${e.excerptId?`<a class="text-btn" href="#excerpt/${encodeURIComponent(e.excerptId)}">${esc(excerptBank?.find(p=>p.id===e.excerptId)?.heading||'View the passage')}</a>`:''}${e.note?`<p class="checkin-note">${esc(e.note)}</p>`:''}<div class="passage-actions"><button class="text-btn" data-edit-checkin="${esc(e.id)}">Edit</button><button class="text-btn" data-delete-checkin="${esc(e.id)}">Remove</button></div></div>`).join(''):'<p class="empty">No saved moments in this view. Nothing to catch up on.</p>'}${lastDeletedCheckin?button('Undo last removal','undo-checkin','secondary'):''}<details><summary>Data & privacy</summary><p class="small">History is browser-local and not app-encrypted. It won’t follow your ChatGPT login to another device. Safari website-data clearing can remove it. The app never infers how unlogged days felt.</p>${button('Download my history as JSON','export-checkins','secondary')}${button('Delete all saved check-ins','delete-checkins','text-btn')}${checkinReadError?'<p class="warning">History could not be read. Export saves the original raw data so you can retain it before clearing.</p>':''}</details>`}
function exportCheckins(){try{const raw=localStorage.getItem(CHECKIN_KEY)||'[]';let payload;try{payload=JSON.stringify({format:'antar-checkins-v1',needReviews:typeof needReviews!=='undefined'?needReviews:[],exportedAt:new Date().toISOString(),entries:JSON.parse(raw)},null,2)}catch{payload=raw}const blob=new Blob([payload],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='antar-checkins-'+AntarPatterns.dateKey(new Date())+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}catch{toast('History could not be exported from this browser.')}}
document.addEventListener('input',e=>{if(!logDraft)return;const fields={'log-at':'at','log-duration':'duration','log-note':'note','log-activity-detail':'activityDetail'};if(fields[e.target.id])logDraft[fields[e.target.id]]=e.target.value;if(e.target.id==='log-intensity'){logDraft.intensity=Number(e.target.value);$('#log-intensity-label').textContent=logDraft.intensity+'/5'}});
document.addEventListener('change',e=>{if(logDraft&&e.target.id==='log-situation')logDraft.situation=e.target.value;if(logDraft&&e.target.id==='log-activity'){logDraft.activity=e.target.value;if(e.target.value!=='reflection')logDraft.excerptId=''}if(e.target.id==='learning-toggle'){const next=e.target.checked;try{localStorage.setItem('antar-learning',next?'on':'off');personalLearning=next;toast(next?'Learning from your saved feedback is on.':'Personal learning is off.')}catch{e.target.checked=personalLearning;toast('Could not save this preference.')}}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.logMood&&logDraft){logMoodPickerOpen=true;const m=el.dataset.logMood;if(logDraft.moods.includes(m))logDraft.moods=logDraft.moods.filter(x=>x!==m);else if(logDraft.moods.length<3)logDraft.moods.push(m);else return toast('Choose up to 3 feelings.');render(true);return}if(el.dataset.logOutcome&&logDraft){logDraft.outcome=el.dataset.logOutcome;render(true);return}if(el.dataset.monthShift){monthOffset=Math.min(0,monthOffset+Number(el.dataset.monthShift));monthDay='';render();return}if(el.dataset.monthDay){monthDay=monthDay===el.dataset.monthDay?'':el.dataset.monthDay;render(true);return}if(el.dataset.editCheckin){const entry=checkins.find(x=>x.id===el.dataset.editCheckin);if(entry){editingCheckin=entry.id;logMoodPickerOpen=false;logDraft={...entry,sourceVersion:JSON.stringify(entry),moods:[...entry.moods],at:localInput(new Date(entry.at)),duration:entry.durationKnown?String(entry.minutes):''};go('log')}return}if(el.dataset.deleteCheckin){const entry=checkins.find(x=>x.id===el.dataset.deleteCheckin);if(entry&&commitCheckins(checkins.filter(x=>x.id!==entry.id))){lastDeletedCheckin=entry;render(true);toast('Removed. You can undo it below.')}return}
 const a=el.dataset.action||'';if(a==='new-checkin'){beginCheckin();return}if(a.startsWith('log-passage:')){beginCheckin(a.slice(12));return}if(a==='cancel-checkin'){logDraft=null;editingCheckin=null;go('month');return}if(a==='clear-day'){monthDay='';render(true);return}if(a==='save-checkin'){
  const d=logDraft,at=Date.parse(d.at),duration=d.duration.trim(),minutes=duration===''?0:Number(duration);const error=$('#log-error');if(checkinReadError){error.textContent='Download or explicitly clear the unreadable history before saving.';return}if(!d.moods.length){error.textContent='Choose a feeling, or “Not sure.”';return}if(!Number.isFinite(at)||at>Date.now()+60000){error.textContent='Choose a valid time up to the present.';return}if(!Number.isInteger(minutes)||minutes<0||minutes>1440){error.textContent='Duration should be 0–1440 whole minutes, or left blank.';return}if(checkins.length>=5000&&!editingCheckin){error.textContent='This browser has 5,000 entries. Export a backup before making room.';return}
  if(editingCheckin&&d.sourceVersion){try{const latest=JSON.parse(localStorage.getItem(CHECKIN_KEY)||'[]').find(x=>x.id===editingCheckin);if(!latest||JSON.stringify(latest)!==d.sourceVersion){error.textContent='This log changed in another tab. Cancel and reopen its latest version before saving; your draft is still here.';return}}catch{error.textContent='The saved history could not be checked safely.';return}}
  const entry={id:editingCheckin||crypto.randomUUID(),at:new Date(at).toISOString(),kind:d.kind==='followup'?'followup':'difficult',moods:[...d.moods],intensity:d.intensity,situation:d.situation,nuance:d.nuance||'',need:d.need||'',minutes,durationKnown:duration!=='',activity:d.activity,activityDetail:(d.activityDetail||'').trim().slice(0,120),outcome:d.activity?d.outcome:'unsure',excerptId:d.activity==='reflection'?d.excerptId:'',feltChange:d.feltChange||'',comfortId:d.comfortId||'',note:d.note.slice(0,600)};const next=editingCheckin?checkins.map(x=>x.id===editingCheckin?entry:x):[...checkins,entry];if(commitCheckins(next)){logDraft=null;editingCheckin=null;const savedDate=new Date(entry.at),today=new Date();monthOffset=(savedDate.getFullYear()-today.getFullYear())*12+savedDate.getMonth()-today.getMonth();monthDay=AntarPatterns.dateKey(savedDate);logFilters={mood:'any',need:'any',situation:'any',outcome:'any',q:'',from:'',to:''};historyEvidenceIds=null;go('month');toast('Saved on this device.')}return}
 if(a==='undo-checkin'&&lastDeletedCheckin){if(commitCheckins([...checkins,lastDeletedCheckin])){lastDeletedCheckin=null;render(true)}return}if(a==='export-checkins'){exportCheckins();return}if(a==='delete-checkins'&&confirm('Delete all saved check-ins from this browser? Export a backup first if you want to keep them.')){try{localStorage.removeItem(CHECKIN_KEY);checkins=[];needReviews=[];localStorage.removeItem(NEED_REVIEW_KEY);checkinReadError=false;lastDeletedCheckin=null;logDraft=null;render(true);toast('Saved check-ins deleted.')}catch{toast('Could not clear the saved history.')}}});
